package live.linghe.privateinput;
import java.util.*;
public final class CliRepeatedProbe {
 public static void main(String[] args)throws Exception{long session=NativeCore.create(args[0],args[1]);if(session==0)throw new AssertionError("init");try{InputQuality quality=new InputQuality(new java.io.File(args[2]));for(String raw:new String[]{"4","44","444","4444","44444426","44426","444999999","64426444"}){NativeCore.mode(session,true,true);for(char key:raw.toCharArray()){NativeCore.key(session,key);String[][] state=NativeCore.snapshot(session);System.out.println("STEP "+key+" META "+Arrays.toString(state[0])+" count="+(state.length-1));}String[][] state=NativeCore.snapshot(session);for(int i=1;i<Math.min(6,state.length);i++)System.out.println("ROW "+Arrays.toString(state[i]));long started=System.nanoTime();java.util.List<InputQuality.Repair> repairs=quality.repairs(session,state,true,"","",()->false);System.out.println("REPAIR count="+repairs.size()+" ms="+(System.nanoTime()-started)/1000000);for(int i=0;i<Math.min(5,repairs.size());i++){InputQuality.Repair r=repairs.get(i);System.out.println("PROPOSAL "+r.text+" / "+r.reading+" tail="+r.remainder);}NativeCore.key(session,32);System.out.println("SPACE "+Arrays.toString(NativeCore.snapshot(session)[0]));}}finally{NativeCore.destroy(session);}}
}
